import type {ISystemService} from '#src/system/system.js';
import type {IntranetProbeRequest,IntranetProbeResult,IntranetProbeServiceResponse} from '@knorvia/shared';
export type ProbeTarget = {kind:'tcp';targetId:string;host:string;port:number;timeoutMs:number}|{kind:'service';targetId:string;url:string;expectedMarker?:string;token?:string;timeoutMs:number};
export declare function createSystemServiceOwner(options:{env?:NodeJS.ProcessEnv;isExecutable?:(path:string)=>boolean;platform?:NodeJS.Platform;tcpProbe?:(params:{host:string;port:number;timeoutMs:number})=>Promise<number>;serviceProbe?:(params:{url:string;timeoutMs:number;token?:string})=>Promise<{latencyMs:number;marker?:string}>;now?:()=>number},policy:{plan:(request:IntranetProbeRequest)=>{targets:ProbeTarget[];attempts:number;requiredSuccessCount:number};parseResponse:(payload:unknown)=>IntranetProbeServiceResponse;strategy:(targets:ProbeTarget[])=>IntranetProbeResult['strategy']}):ISystemService;

import type {
  IntranetProbeRequest,
  IntranetProbeResult,
  IntranetProbeServiceResponse,
} from '@knorvia/shared';

export type ProbeTarget =
  | { kind: 'tcp'; targetId: string; host: string; port: number; timeoutMs: number }
  | { kind: 'service'; targetId: string; url: string; expectedMarker?: string; token?: string; timeoutMs: number };

export type TcpParameters = { host: string; port: number; timeoutMs: number };
export type ServiceParameters = { url: string; timeoutMs: number; token?: string };
export type TcpProbe = (params: TcpParameters) => Promise<number>;
export type ServiceProbe = (params: ServiceParameters) => Promise<{ latencyMs: number; marker?: string }>;
export type OwnerOptions = {
  env?: NodeJS.ProcessEnv;
  isExecutable?: (path: string) => boolean;
  platform?: NodeJS.Platform;
  tcpProbe?: TcpProbe;
  serviceProbe?: ServiceProbe;
  now?: () => number;
};
export type OwnerPolicy = {
  plan: (request: IntranetProbeRequest) => {
    targets: ProbeTarget[];
    attempts: number;
    requiredSuccessCount: number;
  };
  parseResponse: (payload: unknown) => IntranetProbeServiceResponse;
  strategy: (targets: ProbeTarget[]) => IntranetProbeResult['strategy'];
};
export type TargetResult = IntranetProbeResult['results'][number];

import { Socket } from 'node:net';
import type { OwnerPolicy, ServiceParameters, TcpParameters } from './contracts.js';

export function probeTcp({ host, port, timeoutMs }: TcpParameters): Promise<number> {
  const startedAt = Date.now();
  return new Promise((resolve, reject) => {
    const socket = new Socket();
    let settled = false;
    const finish = (complete: () => void) => {
      if (settled) return;
      settled = true;
      socket.removeAllListeners();
      socket.destroy();
      complete();
    };
    socket.setTimeout(timeoutMs);
    socket.once('connect', () => {
      const latencyMs = Math.max(0, Date.now() - startedAt);
      finish(() => resolve(latencyMs));
    });
    socket.once('timeout', () => {
      finish(() => reject(new Error(`timeout(${timeoutMs}ms)`)));
    });
    socket.once('error', (error) => {
      finish(() => reject(error));
    });
    socket.connect(port, host);
  });
}

export async function probeHttp(
  params: ServiceParameters,
  parseResponse: OwnerPolicy['parseResponse'],
): Promise<{ latencyMs: number; marker?: string }> {
  const startedAt = Date.now();
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), params.timeoutMs);
  try {
    const response = await fetch(params.url, {
      method: 'GET',
      headers: params.token ? { 'x-knorvia-intranet-token': params.token } : undefined,
      signal: controller.signal,
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const payload: unknown = await response.json();
    const parsed = parseResponse(payload);
    if (!parsed.ok) throw new Error('service returned ok=false');
    return {
      latencyMs: Math.max(0, Date.now() - startedAt),
      marker: parsed.marker,
    };
  } catch (error) {
    if (error instanceof Error && error.name === 'AbortError') {
      throw new Error(`timeout(${params.timeoutMs}ms)`);
    }
    throw error;
  } finally {
    clearTimeout(timeoutId);
  }
}

import type { ProbeTarget, ServiceProbe, TargetResult, TcpProbe } from './contracts.js';

export async function runTarget(
  target: ProbeTarget,
  attempts: number,
  tcpProbe: TcpProbe,
  serviceProbe: ServiceProbe,
): Promise<TargetResult> {
  let lastError = '';
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      if (target.kind === 'tcp') {
        const latencyMs = await tcpProbe({
          host: target.host,
          port: target.port,
          timeoutMs: target.timeoutMs,
        });
        return {
          targetId: target.targetId,
          kind: 'tcp',
          host: target.host,
          port: target.port,
          reachable: true,
          attemptCount: attempt,
          latencyMs,
        };
      }
      const result = await serviceProbe({
        url: target.url,
        timeoutMs: target.timeoutMs,
        token: target.token,
      });
      if (target.expectedMarker && result.marker !== target.expectedMarker) {
        throw new Error(`marker mismatch(expected=${target.expectedMarker}, actual=${result.marker ?? '<empty>'})`);
      }
      return {
        targetId: target.targetId,
        kind: 'service',
        url: target.url,
        reachable: true,
        attemptCount: attempt,
        latencyMs: result.latencyMs,
        marker: result.marker,
      };
    } catch (error) {
      lastError = error instanceof Error ? error.message : String(error);
    }
  }
  if (target.kind === 'tcp') {
    return {
      targetId: target.targetId,
      kind: 'tcp',
      host: target.host,
      port: target.port,
      reachable: false,
      attemptCount: attempts,
      latencyMs: null,
      error: lastError || 'probe failed',
    };
  }
  return {
    targetId: target.targetId,
    kind: 'service',
    url: target.url,
    reachable: false,
    attemptCount: attempts,
    latencyMs: null,
    error: lastError || 'probe failed',
  };
}

import { homedir } from 'node:os';
import type { ISystemService } from '#src/system/system.js';
import { listIntegratedTerminalShellOptions } from '#src/system/integratedTerminalShells.js';
import type { OwnerOptions, OwnerPolicy, ServiceProbe, TcpProbe } from './system-probe/contracts.js';
import { probeHttp, probeTcp } from './system-probe/defaultAdapters.js';
import { runTarget } from './system-probe/targetLifecycle.js';

export function createSystemServiceOwner(
  options: OwnerOptions,
  policy: OwnerPolicy,
): ISystemService {
  const tcpProbe: TcpProbe = options.tcpProbe ?? probeTcp;
  const serviceProbe: ServiceProbe = options.serviceProbe ?? ((params) => probeHttp(params, policy.parseResponse));
