import { dirname, isAbsolute, resolve } from 'node:path';
import { homeToken, withoutComment, words } from './tokens';

export interface Context {
  patterns: string[];
  directives: Array<{ key: string; value: string }>;
  source: string;
  eligibleHost: boolean;
}

export interface Declaration {
  alias: string;
  source: string;
}

async function includeFiles(tokens: string[], directory: string): Promise<string[]> {
  const targets: string[] = [];
  const seen = new Set<string>();
  for (const raw of tokens) {
    const expanded = homeToken(raw);
    if (!expanded) continue;
    const absolute = isAbsolute(expanded) ? expanded : resolve(directory, expanded);
    if (!/[*?\[\]]/.test(absolute)) {
      if (existsSync(absolute) && !seen.has(absolute)) {
        seen.add(absolute);
        targets.push(absolute);
      }
      continue;
    }
    try {
      for await (const match of glob(absolute)) {
        const target = resolve(match);
        if (!seen.has(target)) {
          seen.add(target);
          targets.push(target);
        }
      }
    } catch {
      // Preserve targets yielded before a glob or iterator failure.
    }
  }
  return targets;
}

async function visit(file: string, depth: number, visited: Set<string>): Promise<Context[]> {
  const absolute = resolve(file);
  if (visited.has(absolute) || depth > 8) return [];
  visited.add(absolute);
  let content: string;
  try {
    content = await readFile(absolute, 'utf8');
  } catch {
    return [];
  }
  let current: Context = {
    patterns: ['*'], directives: [], source: absolute, eligibleHost: false,
  };
  const contexts: Context[] = [current];
  for (const raw of content.split(/\r?\n/)) {
    const line = withoutComment(raw).trim();
    if (!line) continue;
    const tokens = words(line);
    const first = tokens[0];
    if (!first) continue;
    const key = first.toLowerCase();
    if (key === 'include') {
      const targets = await includeFiles(tokens.slice(1), dirname(absolute));
      for (const target of targets) {
        contexts.push(...await visit(target, depth + 1, visited));
      }
    } else if (key === 'host') {
      current = {
        patterns: tokens.slice(1), directives: [], source: absolute, eligibleHost: true,
      };
      contexts.push(current);
    } else if (tokens.length >= 2) {
      current.directives.push({ key, value: tokens.slice(1).join(' ') });
    }
  }
  return contexts;
}

export function readContexts(root: string): Promise<Context[]> {
  return visit(root, 0, new Set<string>());
}

export function declarations(contexts: Context[]): Declaration[] {
  const result: Declaration[] = [];
  const admitted = new Set<string>();
  for (const context of contexts) {
    if (!context.eligibleHost || context.patterns.length !== 1) continue;
    const alias = context.patterns[0].trim();
    if (!alias || alias === '*' || alias.startsWith('!') || /[?*\[\\\]]/.test(alias)) continue;
    if (admitted.has(alias)) continue;
    admitted.add(alias);
    result.push({ alias, source: context.source });
    if (result.length === 200) break;
  }
  return result;
}

import type { SSHConfigAliasOption } from '@knorvia/shared';
import type { Context, Declaration } from './configuration';
import { homeToken } from './tokens';

function matchesOne(pattern: string, alias: string): boolean {
  if (pattern === '*') return true;
  if (!/[*?]/.test(pattern)) return pattern === alias;
  let expression = '^';
  for (let index = 0; index < pattern.length; index += 1) {
    const char = pattern.charAt(index);
    if (char === '*') expression += '.*';
    else if (char === '?') expression += '.';
    else expression += /[\\^$.*+?()[\]{}|]/.test(char) ? `\\${char}` : char;
  }
  return new RegExp(`${expression}$`).test(alias);
}

function matchesContext(patterns: string[], alias: string): boolean {
  let positive = false;
  for (const raw of patterns) {
    const pattern = raw.trim();
    if (!pattern) continue;
    if (pattern.startsWith('!')) {
      const excluded = pattern.slice(1);
      if (excluded && matchesOne(excluded, alias)) return false;
    } else if (matchesOne(pattern, alias)) {
      positive = true;
    }
  }
  return positive;
}

export function validPort(value: string): number | undefined {
  const port = parseInt(value.trim(), 10);
  return Number.isInteger(port) && port >= 1 && port <= 65535 ? port : undefined;
}

export function fallbackOption(declaration: Declaration, contexts: Context[]): SSHConfigAliasOption {
  let host: string | undefined;
  let port: number | undefined;
  let username: string | undefined;
  let privateKeyPath: string | undefined;
  for (const context of contexts) {
    if (!matchesContext(context.patterns, declaration.alias)) continue;
    for (const directive of context.directives) {
      if (directive.key === 'hostname' && !host) {
        host = directive.value.trim() || undefined;
      } else if (directive.key === 'user' && !username) {
        username = directive.value.trim() || undefined;
      } else if (directive.key === 'port' && port == null) {
        port = validPort(directive.value);
      } else if (directive.key === 'identityfile' && !privateKeyPath) {
        privateKeyPath = homeToken(directive.value).trim() || undefined;
      }
    }
  }
  return {
    alias: declaration.alias,
    host: host ?? declaration.alias,
    port,
    username,
    privateKeyPath,
    source: declaration.source,
  };
}

export function mergeQuery(output: string | null, fallback: SSHConfigAliasOption): SSHConfigAliasOption {
  if (!output) return fallback;
  const parsed: { host: string | undefined; port: number | undefined; username: string | undefined } = {
    host: undefined, port: undefined, username: undefined,
  };
  for (const raw of output.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line) continue;
    const match = /^(\S+)\s+(.*)$/.exec(line);
    if (!match) continue;
    const key = match[1].toLowerCase();
    const value = match[2].trim();
    if (key === 'hostname' && !parsed.host) parsed.host = value || undefined;
    else if (key === 'user' && !parsed.username) parsed.username = value || undefined;
    else if (key === 'port' && parsed.port == null) parsed.port = validPort(value);
  }
  return {
    alias: fallback.alias,
    host: parsed.host ?? fallback.host ?? fallback.alias,
    port: parsed.port ?? fallback.port,
    username: parsed.username ?? fallback.username,
    privateKeyPath: fallback.privateKeyPath,
    source: fallback.source,
  };
}

import { spawn } from 'node:child_process';
import { existsSync } from 'node:fs';
import { delimiter, join } from 'node:path';

function fromPath(binary: string): string | null {
  const value = process.env['PATH'];
  if (!value) return null;
  for (const raw of value.split(delimiter)) {
    const directory = raw.trim();
    if (!directory) continue;
    const candidate = join(directory, binary);
    if (existsSync(candidate)) return candidate;
  }
  return null;
}

export function findSSH(): string | null {
  if (process.platform !== 'win32') return fromPath('ssh');
  const found = fromPath('ssh.exe');
  if (found) return found;
  const windows = process.env['WINDIR']?.trim() || 'C:\\Windows';
  const programs = process.env['ProgramFiles']?.trim() || 'C:\\Program Files';
  const programsX86 = process.env['ProgramFiles(x86)']?.trim() || 'C:\\Program Files (x86)';
  const candidates = [
    join(windows, 'System32', 'OpenSSH', 'ssh.exe'),
    join(programs, 'OpenSSH', 'ssh.exe'),
    join(programs, 'Git', 'usr', 'bin', 'ssh.exe'),
    join(programsX86, 'Git', 'usr', 'bin', 'ssh.exe'),
  ];
  for (const candidate of candidates) {
    if (existsSync(candidate)) return candidate;
  }
  return null;
}

export function queryAlias(executable: string, root: string, alias: string): Promise<string | null> {
  return new Promise((resolve) => {
    const child = spawn(executable, ['-G', '-F', root, '-o', 'BatchMode=yes', alias], {
      stdio: ['ignore', 'pipe', 'ignore'],
      windowsHide: true,
      env: { ...process.env, SSH_ASKPASS_REQUIRE: 'never', SSH_ASKPASS: '', DISPLAY: '' },
    });
    let finished = false;
    let stdout = '';
    const timer = setTimeout(() => {
      if (finished) return;
      finished = true;
      child.kill();
      resolve(null);
    }, 1500);
    child.stdout.on('data', (chunk: Buffer | string) => {
      if (finished) return;
      stdout = (stdout + chunk.toString()).slice(0, 128000);
    });
    child.on('error', () => {
      if (finished) return;
      finished = true;
      clearTimeout(timer);
      resolve(null);
    });
    child.on('close', (code) => {
      if (finished) return;
      finished = true;
      clearTimeout(timer);
      resolve(code === 0 ? stdout : null);
    });
  });
}

export async function mapWorkers<T, R>(items: T[], requested: number, mapper: (item: T) => Promise<R>): Promise<R[]> {
  if (items.length === 0) return [];
  const count = Math.max(1, Math.min(requested, items.length));
  const output = new Array<R>(items.length);
  let next = 0;
  async function worker(): Promise<void> {
    while (next < items.length) {
      const index = next;
      next += 1;
      output[index] = await mapper(items[index]);
    }
  }
  await Promise.all(Array.from({ length: count }, () => worker()));
  return output;
}

import { homedir } from 'node:os';
import { join } from 'node:path';

export function withoutComment(line: string): string {
  let quote: string | null = null;
  let escaped = false;
  for (let index = 0; index < line.length; index += 1) {
    const char = line.charAt(index);
    if (escaped) {
      escaped = false;
      continue;
    }
    if (char === '\\') {
      escaped = true;
      continue;
    }
    if (quote !== null) {
      if (char === quote) quote = null;
    } else if (char === '"' || char === "'") {
      quote = char;
    } else if (char === '#') {
      return line.slice(0, index);
    }
  }
  return line;
}

export function words(line: string): string[] {
  const result: string[] = [];
  let current = '';
  let quote: string | null = null;
  for (let index = 0; index < line.length; index += 1) {
    const char = line.charAt(index);
    const next = line.charAt(index + 1);
    if (quote !== null) {
      if (char === quote) {
        quote = null;
      } else if (char === '\\' && next && (next === quote || next === '\\')) {
        current += next;
        index += 1;
      } else {
        current += char;
      }
      continue;
    }
    if (char === '"' || char === "'") {
      quote = char;
    } else if (char === '\\' && next && (/\s/.test(next) || next === '\\' || next === '"' || next === "'" || next === '#')) {
      current += next;
      index += 1;
    } else if (/\s/.test(char)) {
      if (current.length > 0) result.push(current);
      current = '';
    } else {
      current += char;
    }
  }
  if (current.length > 0) result.push(current);
  return result;
}

export function homeToken(raw: string): string {
  const value = raw.trim();
  if (!value) return '';
  const home = homedir();
  const expanded = value.replace(/^%d(?=$|[/\\])/, () => home);
  if (expanded === '~') return home;
  if (expanded.startsWith('~/') || expanded.startsWith('~\\')) {
    return join(home, expanded.slice(2));
  }
  return expanded;
}

import type { SSHConfigAliasOption } from '@knorvia/shared';
import { existsSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { declarations, readContexts } from './ssh-alias/configuration';
import { fallbackOption, mergeQuery } from './ssh-alias/fallback';
import { findSSH, mapWorkers, queryAlias } from './ssh-alias/query';

let cache: { expiresAt: number; options: SSHConfigAliasOption[] } | null = null;

export async function listSSHConfigAliasesFromLocalConfig(): Promise<SSHConfigAliasOption[]> {
  const now = Date.now();
  if (cache !== null && cache.expiresAt > now) {
    return cache.options.map((option) => ({ ...option }));
  }
  const root = join(homedir(), '.ssh', 'config');
  if (!existsSync(root)) {
    cache = { expiresAt: now + 30000, options: [] };
    return [];
  }
  const contexts = await readContexts(root);
  const aliases = declarations(contexts);
  if (aliases.length === 0) {
    cache = { expiresAt: now + 30000, options: [] };
    return [];
  }
  const fallback = aliases.map((alias) => fallbackOption(alias, contexts));
  const executable = findSSH();
  const options = executable === null ? fallback : await mapWorkers(fallback, 3, async (option) => {
    const output = await queryAlias(executable, root, option.alias);
    return mergeQuery(output, option);
  });
  cache = { expiresAt: now + 30000, options };
  return options.map((option) => ({ ...option }));
}

