  const candidates = [
    join(windows, 'System32', 'OpenSSH', 'ssh.exe'),
    join(programs, 'OpenSSH', 'ssh.exe'),
    join(programs, 'Git', 'usr', 'bin', 'ssh.exe'),
    join(programsX86, 'Git', 'usr', 'bin', 'ssh.exe'),
